using System;
using System.Collections.Generic;
using System.Reflection;
using System.Reflection.Emit;
using HarmonyLib;
using McnCraft;
using UnityEngine;

namespace MPatcherFork.CustomPatches
{
	// Audited forces generated by the craft itself. Weapon/blast forces require
	// the emitting craft, never the mass factor of an arbitrary hit target.
	internal static class MagnificationForceUnits
	{
		internal static readonly int[] Tokens = { 0x06001B75, 0x060025FC, 0x06002613, 0x06002620, 0x06002632, 0x06002642,
			0x06002679, 0x0600267E, 0x06002681, 0x06002A14, 0x0600415D, 0x060041B0, 0x060041C8, 0x060041D8, 0x060055C0, 0x06005C40, 0x06005CC4, 0x06005DC0 };
		private static readonly HashSet<string> logged = new HashSet<string>();
		private static readonly HashSet<int> agdLogged = new HashSet<int>();
		private static readonly FieldInfo agdCommand = AccessTools.Field(typeof(AGDeviceController), "DHFJNLCFCON");
		internal static int Calls;
		internal static MachineController Machine(Component owner)
		{
			MachineController machine = owner as MachineController;
			if (machine != null) return machine;
			PartsController part = owner as PartsController;
			if (part != null) return part.FPEBEEJGFPI;
			BodyController body = owner as BodyController;
			return body == null ? null : body.CIPOPAGDJDE;
		}
		private static float Scale(Component owner) { return MagnificationScalePolicy.Enabled ? MagnificationPhysicsMode.PhysicsScale(Machine(owner)) : 1f; }
		internal static float LinearFactor(float scale, ForceMode mode)
		{
			float s = MagnificationScalePolicy.Valid(scale);
			return mode == ForceMode.Force ? MagnificationScalePolicy.Force(s) : mode == ForceMode.Impulse ? MagnificationScalePolicy.Mass(s) * s : mode == ForceMode.VelocityChange ? s : MagnificationScalePolicy.Acceleration(s);
		}
		internal static void AtPosition(Rigidbody body, Vector3 force, Vector3 position, Component owner) { AtPositionMode(body, force, position, ForceMode.Force, owner); }
		private static void AtPositionMode(Rigidbody body, Vector3 force, Vector3 position, ForceMode mode, Component owner)
		{
            if (MagnificationPhysicsMode.IsVanilla(Machine(owner))) { body.AddForceAtPosition(force, position, mode); return; }
			float factor = LinearFactor(Scale(owner), mode);
			if (MagnificationScalePolicy.Enabled && owner is AGDeviceController && agdLogged.Add(owner.GetInstanceID()))
				MagnificationDownscale.Log("AGD_UNITS_APPLIED command=" + agdCommand.GetValue(owner) + " scale=" + Scale(owner)
					+ " sourceBodyMass=" + MagnificationMassBoundary.Read(body) + " physicalBodyMass=" + body.mass
					+ " sourceForce=" + force.ToString("R") + " physicalForce=" + (force * factor).ToString("R") + " commandUnits=unchanged");
			Observe(owner, force, factor, mode); body.AddForceAtPosition(force * factor, position, mode);
		}
		private static void Force(Rigidbody body, Vector3 force, Component owner) { ForceModeValue(body, force, ForceMode.Force, owner); }
		private static void ForceModeValue(Rigidbody body, Vector3 force, ForceMode mode, Component owner)
		{
            if (MagnificationPhysicsMode.IsVanilla(Machine(owner))) { body.AddForce(force, mode); return; }
			float factor = LinearFactor(Scale(owner), mode);
			Observe(owner, force, factor, mode); body.AddForce(force * factor, mode);
		}
		private static void Torque(Rigidbody body, Vector3 torque, Component owner) { TorqueMode(body, torque, ForceMode.Force, owner); }
		private static void TorqueMode(Rigidbody body, Vector3 torque, ForceMode mode, Component owner)
		{
            if (MagnificationPhysicsMode.IsVanilla(Machine(owner))) { body.AddTorque(torque, mode); return; }
			float s = Scale(owner);
			float factor = mode == ForceMode.Force ? MagnificationScalePolicy.Torque(s) : mode == ForceMode.Impulse ? MagnificationScalePolicy.Inertia(s) : 1f;
			Observe(owner, torque, factor, mode); body.AddTorque(torque * factor, mode);
		}
        private static Vector3 PointVelocity(Rigidbody body, Vector3 position, Component owner)
        {
            if (MagnificationPhysicsMode.IsVanilla(Machine(owner))) return body.GetPointVelocity(position);
            return body.GetPointVelocity(position) / Scale(owner);
        }
        private static Vector3 Velocity(Rigidbody body, Component owner)
        {
            if (MagnificationPhysicsMode.IsVanilla(Machine(owner))) return body.velocity;
            return body.velocity / Scale(owner);
        }
		private static void Observe(Component owner, Vector3 source, float factor, ForceMode mode)
		{
			if (!MagnificationScalePolicy.Enabled) return;
			Calls++;
			if (!(source.sqrMagnitude > 0f)) return;
			string key = owner.GetType().Name + ":" + mode;
			if (logged.Add(key)) MagnificationDownscale.Log("FORCE_UNITS_ACTIVE owner=" + key + " factor=" + factor + " source=" + source.ToString("R") + " physical=" + (source * factor).ToString("R"));
		}
		internal static void Register(Harmony harmony)
		{
			foreach (int token in Tokens)
			{
				MethodInfo method = (MethodInfo)typeof(MachineController).Module.ResolveMethod(token);
				harmony.Patch(method, null, null, new HarmonyMethod(AccessTools.Method(typeof(MagnificationForceUnits), "Transpiler")), null);
				MagnificationDownscale.Log("FORCE_UNITS_HOOK target=" + method.DeclaringType.Name + "." + method.Name + " token=" + token.ToString("X8") + " source=own-craft");
			}
		}
		internal static IEnumerable<CodeInstruction> Transpiler(IEnumerable<CodeInstruction> instructions, MethodBase __originalMethod)
		{
			int forces = 0;
			foreach (CodeInstruction source in instructions)
			{
				CodeInstruction code = new CodeInstruction(source);
				MethodInfo call = code.operand as MethodInfo;
				string replacement = null;
				if (call != null && call.DeclaringType == typeof(Rigidbody))
				{
					int n = call.GetParameters().Length;
					if (call.Name == "AddForceAtPosition") replacement = n == 2 ? "AtPosition" : n == 3 ? "AtPositionMode" : null;
					if (call.Name == "AddForce") replacement = n == 1 ? "Force" : n == 2 ? "ForceModeValue" : null;
					if (call.Name == "AddTorque") replacement = n == 1 ? "Torque" : n == 2 ? "TorqueMode" : null;
					if (replacement != null) forces++;
					if (call.Name == "GetPointVelocity" && (__originalMethod.DeclaringType == typeof(AGDeviceController) || __originalMethod.DeclaringType == typeof(ThrusterController))) replacement = "PointVelocity";
					if (call.Name == "get_velocity" && __originalMethod.DeclaringType == typeof(WheelController)) replacement = "Velocity";
				}
				if (replacement != null)
				{
					CodeInstruction arg = new CodeInstruction(OpCodes.Ldarg_0);
					arg.labels.AddRange(code.labels); code.labels.Clear(); arg.blocks.AddRange(code.blocks); code.blocks.Clear();
					yield return arg; code.opcode = OpCodes.Call; code.operand = AccessTools.Method(typeof(MagnificationForceUnits), replacement);
				}
				yield return code;
			}
			// Recovered MPatcher may replace both Body.FixedUpdate water calls.
			if (forces == 0 && __originalMethod.MetadataToken != 0x06002613) throw new InvalidOperationException("missing-own-craft-force " + __originalMethod);
		}
		internal static void Clear() { Calls = 0; logged.Clear(); agdLogged.Clear(); }
	}
}
